-- Seed do banco Carteira B3 (fonte única; `prisma db seed` só executa este arquivo).
-- Uso: npm run db:seed (num banco migrado).
-- Idempotente: rodar duas vezes não muda nada. Cada linha tem UUID fixo e legível, e cada INSERT usa
-- ON CONFLICT DO NOTHING pela chave natural, ou pelo id quando a tabela não tem chave natural (operations,
-- price_alerts), ou sem alvo quando a PK já é a chave natural (cotações, preços, itens de lista): ticker, CNPJ, código do índice, nome do tipo de título, (pai, nome) do
-- setor, (tipo, vencimento) do título. Linha cuja chave natural pode ser nula (corretora ou emissor sem CNPJ, setor de
-- primeiro nível, ativo de renda fixa sem ticker) é filtrada com NOT EXISTS sobre a mesma chave, porque NULL não
-- conflita no UNIQUE. Assim, o K5 pode fazer upsert pelo ticker/ISIN depois do seed, e o seed depois do K5, sem duplicar.
-- Faixas de UUID (último grupo): proventos 0000xx, corretoras 0001xx, setores 0003xx, emissores 0004xx, ativos 0005xx,
-- tipos de título 0006xx, índices econômicos 0009xx, usuários 0010xx, carteiras 0011xx, lotes de importação 0012xx,
-- operações 0013xx, proventos recebidos 0014xx, categorias de IR 0015xx, apurações 0016xx, DARF 0017xx,
-- demonstrações 0018xx, informes mensais de FII 0019xx, informes trimestrais 0020xx, documentos 0021xx,
-- eventos corporativos 0022xx, indicadores 0023xx, alertas 0024xx, telas salvas 0025xx.
-- Ordem das seções: 1. catálogo (BD-1, primeiro corte do P1: o que o S1 lê) → 2. mercado (D59, PF e P1-2) →
-- 3. imposto de renda (P0) → 4. usuários → 5. acompanhamento e planejamento (P1-2).
-- Nas seções 2 a 5, a linha acha o pai pela chave natural (ISIN, ticker, CNPJ, código, e-mail, nome da carteira) com
-- LEFT JOIN: se o pai não existir, a FK vem nula e o INSERT falha no NOT NULL, em vez de pular a linha em silêncio (a
-- seção 1 usa o UUID fixo do pai; crypto_assets usa JOIN, e o seed-check acusa cripto sem a especialização). Exceções, com FK que
-- aceita nulo, conferidas pelo database/tests/seed-check.sql: operations.import_batch_id (lote confirmado com tantas
-- operações quanto linhas), tax_assessments.darf_id (imposto devido > 0 se e só se há DARF) e
-- saved_screens.sort_indicator_id (só as três telas previstas ficam sem ordenação).
-- Arquivos de origem, URL, hash e mapeamento: database/docs/fontes-poc.md.

BEGIN;

-- ============================================================ 1. catálogo (BD-1)
-- Gerado a partir dos arquivos de data/raw listados em cada bloco (database/docs/fontes-poc.md, seção 6).

-- 1.1 brokers. Nome como a corretora aparece para o investidor (o da massa do handoff: XP Investimentos,
-- NuInvest, Rico); CNPJ do cadastro de intermediários da CVM, situação "EM FUNCIONAMENTO NORMAL"
--   (https://dados.cvm.gov.br/dados/INTERMED/CAD/DADOS/cad_intermed.zip, data/raw/cvm-intermed/).
-- Rico sem CNPJ: a Rico CTVM (13.434.335/0001-60) foi incorporada em 04/10/2018 (CVM, "INCORPORAÇÃO") e a marca
-- opera pela XP Investimentos CCTVM, cujo CNPJ já está na XP (brokers.cnpj é único).
-- Mercado Bitcoin e Foxbit sem CNPJ: exchanges de cripto (D44), não são intermediários cadastrados na CVM.
-- Chave natural: cnpj (UNIQUE); sem CNPJ, o nome (NOT EXISTS), porque NULL não conflita no UNIQUE.
INSERT INTO brokers (id, name, cnpj)
SELECT v.id::uuid, v.name, v.cnpj
FROM (VALUES
  ('00000000-0000-0000-0000-000000000101', 'XP Investimentos', '02332886000104'), -- XP INVESTIMENTOS CCTVM S.A.
  ('00000000-0000-0000-0000-000000000102', 'Rico', NULL),
  ('00000000-0000-0000-0000-000000000103', 'NuInvest', '62169875000179'), -- Nu Investimentos S.A. - CTVM
  ('00000000-0000-0000-0000-000000000104', 'BTG Pactual', '43815158000122'), -- BTG PACTUAL CTVM S/A
  ('00000000-0000-0000-0000-000000000105', 'Itaú Corretora', '61194353000164'), -- ITAU CORRETORA DE VALORES SA
  ('00000000-0000-0000-0000-000000000106', 'Genial Investimentos', '27652684000162'), -- GENIAL INVESTIMENTOS CORRETORA DE VALORES MOBILIÁRIOS S.A.
  ('00000000-0000-0000-0000-000000000107', 'Ágora Investimentos', '74014747000135'), -- AGORA CTVM S.A.
  ('00000000-0000-0000-0000-000000000108', 'Inter DTVM', '18945670000146'), -- INTER DISTRIBUIDORA DE TÍTULOS E VALORES MOBILIÁRIOS
  ('00000000-0000-0000-0000-000000000109', 'Santander Corretora', '29162769000198'), -- SANTANDER CORRETORA DE TÍTULOS E VALORES MOBILIARIOS S/A
  ('00000000-0000-0000-0000-000000000110', 'Mercado Bitcoin', NULL),
  ('00000000-0000-0000-0000-000000000111', 'Foxbit', NULL)
) AS v (id, name, cnpj)
WHERE NOT EXISTS (SELECT 1 FROM brokers b WHERE b.name = v.name)
ON CONFLICT (cnpj) DO NOTHING;

